"use strict";(self.webpackChunknaver_maps_webview_bridge_sdk_docs=self.webpackChunknaver_maps_webview_bridge_sdk_docs||[]).push([["6432"],{9445(e){e.exports=JSON.parse('{"version":{"pluginId":"external","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"externalGuideSidebar":[{"type":"link","href":"/webview-bridge-sdk/","label":"Introduction","docId":"index","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/getting-started","label":"Getting Started","docId":"getting-started","unlisted":false},{"type":"category","label":"API","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Messages","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/webview-bridge-sdk/api/messages/dismissSelf","label":"dismissSelf()","docId":"api/messages/dismissSelf","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/sendClickCode","label":"sendClickCode()","docId":"api/messages/sendClickCode","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/copyToClipboard","label":"copyToClipboard()","docId":"api/messages/copyToClipboard","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/saveBookmark","label":"saveBookmark()","docId":"api/messages/saveBookmark","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/share","label":"share()","docId":"api/messages/share","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/share_url","label":"shareUrl()","docId":"api/messages/share_url","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/setStatusBar","label":"setStatusBar()","docId":"api/messages/setStatusBar","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/tel","label":"tel()","docId":"api/messages/tel","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/externalLink","label":"externalLink()","docId":"api/messages/externalLink","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/composite","label":"composite()","docId":"api/messages/composite","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/setWebViewMeta","label":"setWebViewMeta()","docId":"api/messages/setWebViewMeta","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/openUrl","label":"openUrl()","docId":"api/messages/openUrl","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/requestPermission","label":"requestPermission()","docId":"api/messages/requestPermission","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/getCurrentPosition","label":"getCurrentPosition()","docId":"api/messages/getCurrentPosition","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/watchPosition","label":"watchPosition() / clearWatchPosition()","docId":"api/messages/watchPosition","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/api/messages/openPartnerAuthUrl","label":"openPartnerAuthUrl()","docId":"api/messages/openPartnerAuthUrl","unlisted":false}],"href":"/webview-bridge-sdk/category/messages"},{"type":"category","label":"Utilities","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/webview-bridge-sdk/api/utilities/getWebviewContext","label":"getWebviewContext()","docId":"api/utilities/getWebviewContext","unlisted":false}],"href":"/webview-bridge-sdk/category/utilities"}],"href":"/webview-bridge-sdk/api"},{"type":"category","label":"UI Context","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/webview-bridge-sdk/ui-context/dark-mode-orientation","label":"Theme & Orientation","docId":"ui-context/dark-mode-orientation","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/ui-context/safe-area","label":"Safe Area","docId":"ui-context/safe-area","unlisted":false},{"type":"link","href":"/webview-bridge-sdk/ui-context/webview-meta","label":"WebView Meta","docId":"ui-context/webview-meta","unlisted":false}],"href":"/webview-bridge-sdk/category/ui-context"},{"type":"link","href":"/webview-bridge-sdk/releases","label":"Releases","docId":"releases","unlisted":false}]},"docs":{"api/messages/composite":{"id":"api/messages/composite","title":"composite()","description":"Sends multiple Bridge API calls to the native app in a single message. Use this to batch operations that should be applied atomically or at the same time, reducing round-trip overhead.","sidebar":"externalGuideSidebar"},"api/messages/copyToClipboard":{"id":"api/messages/copyToClipboard","title":"copyToClipboard()","description":"Copies a string to the device clipboard using the native clipboard API, then optionally shows a native toast notification to confirm the action.","sidebar":"externalGuideSidebar"},"api/messages/dismissSelf":{"id":"api/messages/dismissSelf","title":"dismissSelf()","description":"Closes the current webview and returns the user to the native app screen that opened it.","sidebar":"externalGuideSidebar"},"api/messages/externalLink":{"id":"api/messages/externalLink","title":"externalLink()","description":"Opens a URL in the device\'s default external browser, outside of the NAVER Maps app webview.","sidebar":"externalGuideSidebar"},"api/messages/getCurrentPosition":{"id":"api/messages/getCurrentPosition","title":"getCurrentPosition()","description":"Retrieves the current location once through a callback interface, while delegating the actual location lookup and permission handling to the native app.","sidebar":"externalGuideSidebar"},"api/messages/openPartnerAuthUrl":{"id":"api/messages/openPartnerAuthUrl","title":"openPartnerAuthUrl()","description":"Opens a partner authentication URL in the authentication browser appropriate for the current platform.","sidebar":"externalGuideSidebar"},"api/messages/openUrl":{"id":"api/messages/openUrl","title":"openUrl()","description":"Opens a URL in an in-app webview, system webview, or auth browser depending on the browser value.","sidebar":"externalGuideSidebar"},"api/messages/requestPermission":{"id":"api/messages/requestPermission","title":"requestPermission()","description":"Requests an OS-level permission (e.g. location) before you actually use a feature that needs it.","sidebar":"externalGuideSidebar"},"api/messages/saveBookmark":{"id":"api/messages/saveBookmark","title":"saveBookmark()","description":"Saves a place or location entity to the current user\'s NAVER Maps bookmarks.","sidebar":"externalGuideSidebar"},"api/messages/sendClickCode":{"id":"api/messages/sendClickCode","title":"sendClickCode()","description":"Reports a user interaction event to the native analytics layer. Use this to log button clicks, view impressions, or other meaningful in-page events so they can be tracked alongside native app telemetry.","sidebar":"externalGuideSidebar"},"api/messages/setStatusBar":{"id":"api/messages/setStatusBar","title":"setStatusBar()","description":"Changes the background color of the native status bar (the OS bar at the top of the screen showing time, battery, etc.). Use this to match the status bar to your page\'s visual design.","sidebar":"externalGuideSidebar"},"api/messages/setWebViewMeta":{"id":"api/messages/setWebViewMeta","title":"setWebViewMeta()","description":"Updates native UI configuration for the current webview at runtime. This is the imperative counterpart to the declarative window.MAPSWEBVIEWMETA approach described in WebView Meta.","sidebar":"externalGuideSidebar"},"api/messages/share":{"id":"api/messages/share","title":"share()","description":"Opens the native share sheet to share a place or location entity. The native app constructs the share payload (deep-link URL, preview card, etc.) from the supplied id and type.","sidebar":"externalGuideSidebar"},"api/messages/share_url":{"id":"api/messages/share_url","title":"shareUrl()","description":"Opens the native share sheet to share an arbitrary URL. Use this when you want to share a link that is not tied to a specific NAVER Maps entity (e.g. a custom deep-link or a web URL).","sidebar":"externalGuideSidebar"},"api/messages/tel":{"id":"api/messages/tel","title":"tel()","description":"Initiates a phone call to the given number via the device\'s native dialer.","sidebar":"externalGuideSidebar"},"api/messages/watchPosition":{"id":"api/messages/watchPosition","title":"watchPosition() / clearWatchPosition()","description":"Subscribes to ongoing location updates through a callback interface, while delegating the actual location lookup and permission handling to the native app.","sidebar":"externalGuideSidebar"},"api/utilities/getWebviewContext":{"id":"api/utilities/getWebviewContext","title":"getWebviewContext()","description":"Parses the User-Agent string to determine whether the page is running inside the NAVER Maps app at a supported version, and extracts the app\'s current UI context (theme and orientation).","sidebar":"externalGuideSidebar"},"getting-started":{"id":"getting-started","title":"Getting Started","description":"Prerequisites","sidebar":"externalGuideSidebar"},"index":{"id":"index","title":"NAVER Maps WebView Bridge SDK","description":"The NAVER Maps WebView Bridge SDK is a JavaScript SDK that enables webviews embedded in the NAVER Maps app to communicate bidirectionally with the native layer. It abstracts platform-specific native APIs (iOS / Android) into a unified JavaScript interface, so your web application can call native features and receive native events without writing any platform-specific code.","sidebar":"externalGuideSidebar"},"releases":{"id":"releases","title":"Releases","description":"Release notes for the NAVER Maps WebView Bridge SDK. For installation instructions, see Getting Started \u2014 Setup.","sidebar":"externalGuideSidebar"},"ui-context/dark-mode-orientation":{"id":"ui-context/dark-mode-orientation","title":"Theme & Orientation","description":"The NAVER Maps app propagates its current color scheme (light / dark) and device orientation (portrait / landscape) to your webview. You can consume these values via CSS media queries, JavaScript event listeners, or \u2014 for SSR use cases \u2014 by parsing the User-Agent string.","sidebar":"externalGuideSidebar"},"ui-context/safe-area":{"id":"ui-context/safe-area","title":"Safe Area","description":"Modern mobile devices have hardware features \u2014 notches, camera cut-outs, rounded corners, and home indicators \u2014 that encroach on the usable screen area. The NAVER Maps app injects safe area inset values as CSS custom properties into your webview so you can offset your layout accordingly.","sidebar":"externalGuideSidebar"},"ui-context/webview-meta":{"id":"ui-context/webview-meta","title":"WebView Meta","description":"WebView Meta is a configuration object that lets your page declare native UI settings \u2014 such as the status bar color \u2014 at page load time, before any user interaction. Settings are read by the SDK during initialization and sent to the native app automatically.","sidebar":"externalGuideSidebar"}}}}')}}]);